    private final Actions actions;
    private final int bg=NativeTheme.BG,panel=NativeTheme.PANEL,edge=NativeTheme.EDGE,ink=NativeTheme.INK,dim=NativeTheme.DIM,cyan=NativeTheme.ACCENT,pink=0xffF080AC,purple=0xffB69AFF,blue=0xff79A8FF,gold=0xffE5C374;
    private final Map<String,TextView> labels=new HashMap<>();
    private JSONObject summary=new JSONObject(),terminal=new JSONObject();
    private LinearLayout ticker,rules,feed,stats;private Spinner model;private NativeChart chart;private Pipeline pipeline;private Gauge gauge;private TextView priceTab,equityTab;
    private String group="All",bot="",selected="",modelSignature="",marketSignature="",ruleSignature="",feedSignature="";private boolean binding=false,equity=false,connected=false,paused=false; private String statsSignature="",origin="";
